#nullable enable // autogenerated

using System;
using MVZ2Logic.Definitions;
using MVZ2Logic.Localization;
using MVZ2Logic.Options;

namespace MVZ2Logic.Contents.Options
{
    [AutoOptionWidgetDefinition(LogicOptionWidgetNames.lastSponsorAttemptTime)]
    public class LastSponsorAttemptTimeOptionLabel : OptionLabelDefinition
    {
        public LastSponsorAttemptTimeOptionLabel(string nsp, string name) : base(nsp, name)
        {
        }
        public override string GetLabelValue(IOptionContext context)
        {
            long time = Global.Sponsors.GetLastAttemptTime();
            if (time <= 0)
            {
                return Global.Localization.GetText(LogicStrings.INVALID_SPONSOR_TIME);
            }
            var dateTime = DateTimeOffset.FromUnixTimeSeconds(time).LocalDateTime;
            return dateTime.ToString("yyyy-MM-dd HH:mm:ss");
        }
    }
}
